  const c=entry.context;if(c&&((c.roundLabel!==undefined&&!str(c.roundLabel,80))||!num(c.gameNumber,1,15)||!num(c.bestOf,1,15)||!Array.isArray(c.pair)||c.pair.length!==2||!Array.isArray(c.wins)||c.wins.length!==2||c.pair.some(n=>!num(n,0,35))||c.wins.some(n=>!num(n,0,15))))bad('Invalid feat series');
  const local=new Set();for(const f of entry.feats){if(!f||!str(f.id)||local.has(f.id)||!str(f.eventId)||!str(f.text,2000)||!str(f.label,500)||!str(f.name,80)||!str(f.type,50)||!num(f.playerId,0,10000000)||![0,1].includes(f.side)||!num(f.priority,0,120)||!f.e||!num(f.e.period,0,19)||!num(f.e.seconds,0,50000)||!num(f.e.timeMs,0,50000000)||!Array.isArray(f.e.score)||f.e.score.length!==2||f.e.score.some(n=>!num(n,0,5000)))bad('Invalid player feat');local.add(f.id);}
  if(entry.published.some(id=>!local.has(id)))bad('Invalid feat publication');
